mapper.select:
SELECT member_id, email, nickname, profile_image, role, status, created_at, updated_at
FROM member
WHERE 1 = 1

  AND (
    email LIKE CONCAT('%', #{keyword}, '%')
    OR nickname LIKE CONCAT('%', #{keyword}, '%')
  )


  AND status = #{status}

ORDER BY created_at DESC, member_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT api_log_id, member_id, provider, endpoint, request_summary, response_status, success, error_message, created_at FROM external_api_log WHERE 1 = 1
AND provider = #{provider}
AND success = TRUE AND success = FALSE ORDER BY created_at DESC, api_log_id DESC LIMIT #{limit} OFFSET #{offset}
